-- Secret records and secret_ref targets (SECRETS-003, F35, CONTEXT_PACK §7, §8.6, §8.7). Generated by `pnpm db:generate` from
-- src/schema/secrets.ts, then reviewed. Forward-only: never edit once applied; add a new migration.
-- `envelope` and `external_locator` hold ciphertext envelopes and external-store pointers, NEVER plaintext;
-- the *_no_plaintext_check constraints reject the obvious plaintext keys as a guard (the only writer encrypts first).
CREATE TABLE "secret_versions" (
	"tenant_id" uuid NOT NULL,
	"secret_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"envelope" jsonb,
	"external_locator" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"retired_at" timestamp with time zone,
	CONSTRAINT "secret_versions_secret_id_version_pk" PRIMARY KEY("secret_id","version"),
	CONSTRAINT "secret_versions_version_check" CHECK ("secret_versions"."version" >= 1),
	CONSTRAINT "secret_versions_envelope_object_check" CHECK ("secret_versions"."envelope" IS NULL OR jsonb_typeof("secret_versions"."envelope") = 'object'),
	CONSTRAINT "secret_versions_locator_object_check" CHECK ("secret_versions"."external_locator" IS NULL OR jsonb_typeof("secret_versions"."external_locator") = 'object'),
	CONSTRAINT "secret_versions_retired_check" CHECK ("secret_versions"."retired_at" IS NULL OR "secret_versions"."retired_at" >= "secret_versions"."created_at"),
	CONSTRAINT "secret_versions_no_plaintext_check" CHECK (NOT (coalesce("secret_versions"."envelope", '{}'::jsonb) ?| array['plaintext', 'secret', 'password']) AND NOT (coalesce("secret_versions"."external_locator", '{}'::jsonb) ?| array['plaintext', 'secret', 'password']))
);
--> statement-breakpoint
ALTER TABLE "secret_versions" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "secrets" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"name" text NOT NULL,
	"type" text,
	"purpose" text,
	"backend" text DEFAULT 'openbao' NOT NULL,
	"envelope" jsonb,
	"external_locator" jsonb,
	"current_version" integer DEFAULT 1 NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "secrets_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "secrets_name_check" CHECK (length("secrets"."name") BETWEEN 1 AND 255 AND "secrets"."name" IS NFC NORMALIZED AND "secrets"."name" !~ '[[:cntrl:]]'),
	CONSTRAINT "secrets_type_check" CHECK ("secrets"."type" IS NULL OR "secrets"."type" IN ('password', 'api_key', 'token', 'certificate', 'ssh_key', 'webhook_secret', 'kms_ref', 'generic')),
	CONSTRAINT "secrets_backend_check" CHECK ("secrets"."backend" IN ('openbao', 'aws_kms', 'vault', 'aws_secrets_manager', 'azure_kv')),
	CONSTRAINT "secrets_status_check" CHECK ("secrets"."status" IN ('active', 'rotating', 'disabled', 'shredded')),
	CONSTRAINT "secrets_current_version_check" CHECK ("secrets"."current_version" >= 1),
	CONSTRAINT "secrets_envelope_object_check" CHECK ("secrets"."envelope" IS NULL OR jsonb_typeof("secrets"."envelope") = 'object'),
	CONSTRAINT "secrets_locator_object_check" CHECK ("secrets"."external_locator" IS NULL OR jsonb_typeof("secrets"."external_locator") = 'object'),
	CONSTRAINT "secrets_external_locator_check" CHECK ("secrets"."backend" NOT IN ('aws_kms', 'vault', 'aws_secrets_manager', 'azure_kv') OR "secrets"."external_locator" IS NOT NULL),
	CONSTRAINT "secrets_has_value_check" CHECK ("secrets"."status" = 'shredded' OR "secrets"."envelope" IS NOT NULL OR "secrets"."external_locator" IS NOT NULL),
	CONSTRAINT "secrets_no_plaintext_check" CHECK (NOT (coalesce("secrets"."envelope", '{}'::jsonb) ?| array['plaintext', 'secret', 'password']) AND NOT (coalesce("secrets"."external_locator", '{}'::jsonb) ?| array['plaintext', 'secret', 'password']))
);
