-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor triggers). Reviewed.
-- FORCE: the owner role is subject to the tenant policy too, so nothing reads across tenants.
ALTER TABLE "secrets" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "secret_versions" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role gets SELECT/INSERT/UPDATE only (no TRUNCATE, never PUBLIC). There is no DELETE: a
-- secret ends as status 'shredded' (envelope removed), so rotation history and the audit trail survive.
-- The owner's default privileges grant bw_app all four DML rights on new tables, so DELETE is revoked explicitly.
REVOKE ALL ON "secrets", "secret_versions" FROM PUBLIC;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "secrets", "secret_versions" FROM bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "secrets" TO bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "secret_versions" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with rotation and status changes (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER secrets_set_updated_at BEFORE UPDATE ON secrets FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
